<template>
  <div class="register-page min-h-screen lg:grid lg:grid-cols-[.85fr_1.15fr]">
    <section class="register-brand relative hidden overflow-hidden lg:flex"><div class="brand-orb orb-one"></div><div class="brand-orb orb-two"></div><div class="relative z-10 flex w-full flex-col justify-between p-12 xl:p-16"><router-link to="/intro" class="flex items-center gap-3 text-white"><span class="brand-logo">芽</span><span class="text-xl font-extrabold">职芽<span class="text-violet-200">.</span></span></router-link><div><p class="mb-4 text-sm font-semibold tracking-[.25em] text-violet-200">JOIN JOBSPROUT</p><h1 class="mb-6 text-5xl font-black leading-tight text-white">从今天开始<br /><span class="text-violet-200">种下职业的芽</span></h1><p class="max-w-md text-lg leading-relaxed text-violet-100/80">无论你是寻找机会的学生，还是寻找人才的企业，都能在职芽找到合适的成长伙伴。</p></div><p class="text-sm text-violet-200/60">已有账号？返回右侧登录</p></div></section>
    <section class="flex min-h-screen items-center justify-center bg-[var(--bg)] px-6 py-10 sm:px-10"><div class="w-full max-w-2xl"><div class="mb-8 flex items-center justify-between lg:hidden"><router-link to="/intro" class="flex items-center gap-3"><span class="mobile-logo">芽</span><span class="text-xl font-extrabold">职芽<span class="text-brand">.</span></span></router-link><ThemeToggle /></div><div class="mb-8 hidden justify-end lg:flex"><ThemeToggle /></div><div class="mb-8"><p class="mb-3 text-sm font-semibold text-brand">CREATE ACCOUNT</p><h2 class="text-3xl font-black tracking-tight sm:text-4xl">创建你的职芽账号</h2><p class="mt-3 text-sm text-slate-500 dark:text-slate-400">选择你的身份，开启专属求职体验</p></div>
      <el-form ref="formRef" :model="form" :rules="rules" label-position="top" @submit.prevent="submit"><div class="grid gap-x-5 sm:grid-cols-2"><el-form-item label="用户名" prop="username"><el-input v-model="form.username" size="large" placeholder="4-20 位用户名"><template #prefix><User /></template></el-input></el-form-item><el-form-item label="昵称" prop="nickname"><el-input v-model="form.nickname" size="large" placeholder="请输入昵称"><template #prefix><Avatar /></template></el-input></el-form-item><el-form-item label="密码" prop="password"><el-input v-model="form.password" size="large" type="password" show-password placeholder="6-20 位密码"><template #prefix><Lock /></template></el-input></el-form-item><el-form-item label="确认密码" prop="confirmPassword"><el-input v-model="form.confirmPassword" size="large" type="password" show-password placeholder="再次输入密码"><template #prefix><Lock /></template></el-input></el-form-item><el-form-item label="邮箱" prop="email"><el-input v-model="form.email" size="large" placeholder="name@example.com"><template #prefix><Message /></template></el-input></el-form-item><el-form-item label="手机号" prop="phone"><el-input v-model="form.phone" size="large" placeholder="请输入手机号"><template #prefix><Iphone /></template></el-input></el-form-item></div><el-form-item label="注册身份" prop="role"><el-radio-group v-model="form.role" class="role-group"><el-radio-button value="STUDENT"><span class="role-title">学生</span><span class="role-desc">寻找实习与校招机会</span></el-radio-button><el-radio-button value="COMPANY"><span class="role-title">招聘方</span><span class="role-desc">发布职位、发现人才</span></el-radio-button><el-radio-button value="ADMIN"><span class="role-title">管理员</span><span class="role-desc">平台运营与审核</span></el-radio-button></el-radio-group></el-form-item><el-checkbox v-model="agreed" class="mb-5">我已阅读并同意用户协议与隐私政策</el-checkbox><el-button class="register-button" :loading="loading" native-type="submit">创建账号</el-button></el-form><div class="mt-8 text-center text-sm text-slate-500">已有账号？<router-link to="/login" class="font-semibold text-brand hover:underline">返回登录</router-link></div></div>
    </section>
  </div>
</template>
<script setup>
import { reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ElNotification, ElMessage } from 'element-plus'
import { Avatar, Iphone, Lock, Message, User } from '@element-plus/icons-vue'
import ThemeToggle from '../../components/ThemeToggle.vue'
import { register } from '../../api/auth'
const router=useRouter(); const formRef=ref(); const loading=ref(false); const agreed=ref(false)
const form=reactive({username:'',password:'',confirmPassword:'',nickname:'',role:'STUDENT',email:'',phone:''})
const validateConfirm=(_,value,callback)=>{value!==form.password?callback(new Error('两次密码不一致')):callback()}
const rules={username:[{required:true,message:'请输入用户名',trigger:'blur'},{min:4,max:20,message:'用户名长度为 4-20 位',trigger:'blur'}],nickname:[{required:true,message:'请输入昵称',trigger:'blur'}],password:[{required:true,message:'请输入密码',trigger:'blur'},{min:6,max:20,message:'密码长度为 6-20 位',trigger:'blur'}],confirmPassword:[{required:true,message:'请再次输入密码',trigger:'blur'},{validator:validateConfirm,trigger:'blur'}],role:[{required:true,message:'请选择注册身份',trigger:'change'}],email:[{required:true,message:'请输入邮箱',trigger:'blur'},{type:'email',message:'邮箱格式不正确',trigger:'blur'}],phone:[{pattern:/^1[3-9]\d{9}$/,message:'手机号格式不正确',trigger:'blur'}]}
async function submit(){if(!formRef.value||!(await formRef.value.validate().catch(()=>false)))return;if(!agreed.value){ElMessage.warning('请先同意用户协议与隐私政策');return}loading.value=true;try{await register({username:form.username,password:form.password,nickname:form.nickname,role:form.role,email:form.email,phone:form.phone});ElNotification({title:'注册成功',message:'欢迎加入职芽，请登录',type:'success',duration:2500,customClass:'sprout-notification'});await router.push('/login')}catch(error){ElNotification({title:'注册失败',message:error?.response?.data?.message||'请稍后重试',type:'error',duration:3000,customClass:'sprout-notification'})}finally{loading.value=false}}
</script>
