ound:linear-gradient(135deg,var(--brand),var(--brand-2))!important;color:#fff!important;font-size:15px;font-weight:700;box-shadow:0 14px 28px -12px var(--shadow-brand);transition:.3s}.register-button:hover{transform:translateY(-2px);box-shadow:0 18px 34px -12px var(--shadow-brand)}
</style>
